function ChannelsField({ value, onValueChange }) {
  return (
    <FieldSet>
      <FieldLegend>Notification channels</FieldLegend>
      <CheckboxGroup value={value} onValueChange={onValueChange}>
        <Checkbox name="email" label="Email" />
        <Checkbox name="sms" label="SMS" />
        <Checkbox name="push" label="Push notifications" />
      </CheckboxGroup>
      {value.length === 0 && (
        <p className="text-sm text-[var(--ui-text-on-status-danger)]">
          Choose at least one channel.
        </p>
      )}
    </FieldSet>
  );
}

function IntelligencePanel({ open, onOpenChange, messages, streaming, onSend, suggestions }) {
  const [draft, setDraft] = React.useState('');
  return (
    <Drawer open={open} onOpenChange={onOpenChange}>
      <DrawerContent side="right">
        <DrawerHeader>
          <DrawerTitle>Assistant</DrawerTitle>
          <DrawerCloseButton />
        </DrawerHeader>
        <DrawerBody className="p-0">
          <ScrollArea className="h-full">
            <div className="flex flex-col gap-4 px-5 py-4">
              {messages.map((m) => (
                <div key={m.id} className="flex gap-3">
                  {m.role === 'assistant' && (
                    <Avatar>
                      <AvatarFallback>AI</AvatarFallback>
                    </Avatar>
                  )}
                  <p className="text-sm leading-relaxed">{m.content}</p>
                </div>
              ))}
              {streaming && (
                <div className="flex items-center gap-3 text-muted-foreground">
                  <Avatar>
                    <AvatarFallback>AI</AvatarFallback>
                  </Avatar>
                  <Spinner />
                </div>
              )}
            </div>
          </ScrollArea>
        </DrawerBody>
        <Separator />
        <DrawerFooter className="flex-col items-stretch gap-3">
          <div className="flex flex-wrap gap-2">
            {suggestions.map((s) => (
              <Chip key={s} onClick={() => setDraft(s)}>{s}</Chip>
            ))}
          </div>
          <form
            className="flex items-end gap-2"
            onSubmit={(e) => {
              e.preventDefault();
              onSend(draft);
              setDraft('');
            }}
          >
            <InputTextArea
              className="flex-1"
              placeholder="Ask anything…"
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
            />
            <ButtonIcon type="submit" aria-label="Send" disabled={!draft.trim()}>
              <SendIcon />
            </ButtonIcon>
          </form>
        </DrawerFooter>
      </DrawerContent>
    </Drawer>
  );
}

function SetupWizard({ open, onOpenChange, onFinish, steps }) {
  const [step, setStep] = React.useState(0);
  const isLast = step === steps.length - 1;
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{steps[step].title}</DialogTitle>
          <Progress value={((step + 1) / steps.length) * 100} />
        </DialogHeader>
        <Form onFormSubmit={() => (isLast ? onFinish() : setStep((s) => s + 1))}>
          <DialogBody>{steps[step].content}</DialogBody>
          <DialogFooter>
            <Button
              variant="ghost"
              type="button"
              disabled={step === 0}
              onClick={() => setStep((s) => s - 1)}
            >
              Back
            </Button>
            <Button type="submit">{isLast ? 'Finish' : 'Next'}</Button>
          </DialogFooter>
        </Form>
      </DialogContent>
    </Dialog>
  );
}
